INSERT INTO categories (key, kind, position, title, description) VALUES ('timeline', 'single', 0, 'Timeline', 'Choose when you enter the Gu world');
INSERT INTO categories (key, kind, position, title, description) VALUES ('prep', 'single', 1, 'Extra Preparation', 'Extra preparation time before entering the Gu world');
INSERT INTO categories (key, kind, position, title, description) VALUES ('race', 'single', 2, 'Race', 'Choose your race and species in the Gu world');
INSERT INTO categories (key, kind, position, title, description) VALUES ('sex', 'single', 3, 'Sex', 'Determine your character''s sex');
INSERT INTO categories (key, kind, position, title, description) VALUES ('appearance', 'single', 4, 'Appearance', 'Your physical appearance and attractiveness');
INSERT INTO categories (key, kind, position, title, description) VALUES ('specialTraits', 'multiple', 5, 'Special Traits', 'Multiple selection allowed');
INSERT INTO categories (key, kind, position, title, description) VALUES ('clanTier', 'single', 6, 'Clan Tier', 'You may freely choose which of the five regions you are born into. You may choose any tier of clan and additionally choose which status you are born into in that clan. If you choose the central continent, you will be born to a sect member instead of in a clan. You may choose to be born into any clan/sect from the story or to be born into one at random according to the chosen criteria.');
INSERT INTO categories (key, kind, position, title, description) VALUES ('specialBirth', 'single', 7, 'Special Birth', 'Special circumstances surrounding your birth');
INSERT INTO categories (key, kind, position, title, description) VALUES ('aptitude', 'single', 8, 'Aptitude', 'It''s time to determine what dictates your mortal life, how you are treated, and your path across the mortal world. If you pick a grade, you will get a random aptitude within that aptitude range. You can roll a 2d10 or use a number generator to get a number between 0-19.');
INSERT INTO categories (key, kind, position, title, description) VALUES ('luck', 'multiple', 9, 'Luck', 'Choose your luck modifications, which will affect your life in various ways. These are lifelong, near-immutable modifications to your luck. Only a peak rank 8 could alter these.');
INSERT INTO categories (key, kind, position, title, description) VALUES ('soul', 'multiple', 10, 'Soul Foundation', 'Buy each lower-level soul foundation to get a specific soul foundation, starting with the ten thousand man soul. Your body also gains the necessary Dao marks/alterations to contain such a powerful soul.');
INSERT INTO categories (key, kind, position, title, description) VALUES ('venerable', 'single', 11, 'Venerable Inheritances', 'May only choose ONE venerable inheritance');
INSERT INTO categories (key, kind, position, title, description) VALUES ('grabBagBundles', 'single', 12, 'Grab Bag Perks', 'Grab bag perks are minor perks that are nice to have but not substantial enough to be full perks by themselves.');
INSERT INTO categories (key, kind, position, title, description) VALUES ('tier1', 'multiple', 13, 'Tier 1 Perks', 'Basic perks to start your cultivation journey');
INSERT INTO categories (key, kind, position, title, description) VALUES ('tier2', 'multiple', 14, 'Tier 2 Perks', 'Moderate perks for established cultivators');
INSERT INTO categories (key, kind, position, title, description) VALUES ('tier3', 'multiple', 15, 'Tier 3 Perks', 'Advanced perks for experienced Gu masters');
INSERT INTO categories (key, kind, position, title, description) VALUES ('tier4', 'multiple', 16, 'Tier 4 Perks', 'Powerful perks for immortal cultivators');
INSERT INTO categories (key, kind, position, title, description) VALUES ('tier5', 'multiple', 17, 'Tier 5 Perks', 'Each additional Tier 5 perk after first costs +200 CP extra');
INSERT INTO categories (key, kind, position, title, description) VALUES ('premiumGu', 'multiple', 18, 'Premium Gu Worms', 'These are special Immortal Gu that have transcended the limit of gu world, it is as if they were the apex masterpiece of a venerable. Only venerables could make them from scratch, while great grandmaster attainment in their path is needed to advance them past rank 6. They won’t need to be fed for 30 years and can fit in mortal apertures. Upon choosing these worms you learn its recipe for rank 6 and may choose when these Gu worms appear in your aperture. You cannot choose these worms from any other perk.');
INSERT INTO categories (key, kind, position, title, description) VALUES ('missions', 'multiple', 19, 'Missions', 'These are objectives that give you extra points, but you have to complete them within 300 years of central content time or you explode and die. Spectral Soul eats your soul, and Heaven''s Will foils any revival methods. You cannot escape the consequence of not completing your missions. You may pick as many missions as you want.');
INSERT INTO categories (key, kind, position, title, description) VALUES ('drawbacks', 'multiple', 20, 'Drawbacks', 'You may take as many drawbacks as you want. However, you may not take drawbacks more than once. Drawbacks overwrite other options picked in this character creator.');
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('timeline-first', 'timeline', 0, 'First Timeline', 'Born November 11th, same time as Fang Yuan. Spectral Soul succeeds, Spring Autumn Cicada never refined. Fang Yuan becomes demonic powerhouse with blood deity.', 150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('timeline-second', 'timeline', 1, 'Second Timeline (Canon)', 'Born same time as Fang Yuan''s first life. His will travels 500 years back before awakening ceremony. Heaven''s will protects him from lethal attempts.', 0, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('timeline-alternative', 'timeline', 2, 'Alternative Timeline', 'You ARE Fang Yuan - he never transmigrates. No Spring Autumn Cicada, but all other benefits. Skip race, location, appearance.', 300, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('prep-extra', 'prep', 0, 'Extra Prep Time', 'Additional 20 years of preparation time (not available for Alternative Timeline)', -50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('race-random', 'race', 0, 'Random Race', 'Born as random race - variant or normal human. All up to luck.', 300, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('race-variant', 'race', 1, 'Variant Human', 'You may choose to be born as any variant human. If you choose dragonman, then you start your own bloodline, with you as the ancestor instead of Duke Long. Thereby being immune to Duke Long''s Dragonman Extermination killer move', 150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('race-human', 'race', 2, 'Human', 'You may choose to be born as a human, a safe choice. Although nothing is safe in the Gu world.', 0, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('sex-choice', 'sex', 0, 'Choose Sex', 'Choose which sex you are born as.', 0, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('sex-random', 'sex', 1, 'Random Sex', 'Randomly determined.', 50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('appear-ugly', 'appearance', 0, 'Extremely Unattractive', 'You will have an extremely ugly appearance, enough to ruin someone''s day should their gaze land upon you.', 50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('appear-average', 'appearance', 1, 'Average Appearance', 'You possess an extremely average appearance.', 0, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('appear-attractive', 'appearance', 2, 'Extremely Attractive', 'You have an extremely attractive appearance, and people will subconsciously treat you better because of it.', -50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('trait-memory', 'specialTraits', 0, 'Eidetic Memory', 'You gain perfect eidetic memory. However, you may still forget things if you wish. This effect isn''t from wisdom path Dao marks, but your natural human path Dao marks imitating wisdom path.', -50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('trait-strength', 'specialTraits', 1, 'Innate Strength', 'You gain innate strength at birth. As a baby, you can break a grown man''s fingers if you aren''t careful. As an adult, you will have the strength of many men. This effect isn''t from strength path Dao marks, but your natural human path Dao marks imitating the strength path.', -50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('trait-transhuman', 'specialTraits', 2, 'Transhumanist', 'Human Path Dao Marks inscribe into you. You can no longer lose your sense of self or humanity and gain extreme resistance to anything that affects the mind. This allows permanent transformation into a beast, immersion in dream realms, or other experiences (or anything else really).', -200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('clan-mortal', 'clanTier', 0, 'Mortal Village', 'You and one parent are the only Gu masters.', 150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('clan-mid', 'clanTier', 1, 'Mid-tier Clan', 'Respectable clan with resources.', 50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('clan-high', 'clanTier', 2, 'High-tier Clan', 'Powerful clan with significant influence.', -50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('clan-super', 'clanTier', 3, 'Super Clan', 'One of the dominant forces in the region. If you pick the Child of an immortal from Superclan, you will be the child of a random immortal from the super clan/sect you picked.', -100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('birth-custom-immortal', 'specialBirth', 0, 'Customized Child of Immortal Expert', 'You are the singular offspring of a pair of rank 6 Immortals. You have the liberty to design their personalities and choose the location and clan affiliation, within reasonable limits. They each possess a rank 6 immortal gu and have grandmaster attainment.', -400, NULL, 0, 0, NULL, NULL, 'Describe your immortal parents (personalities, clan, location):', 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('apt-random', 'aptitude', 0, 'Random Aptitude', 'Roll the dice on your talent.', 150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('apt-d', 'aptitude', 1, 'D-Grade (20%-39%)', 'Poor aptitude.', 50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('apt-c', 'aptitude', 2, 'C-Grade (40%-59%)', 'Average aptitude.', 0, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('apt-b', 'aptitude', 3, 'B-Grade (60%-79%)', 'Above average.', -50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('apt-a', 'aptitude', 4, 'A-Grade (80%-99%)', 'Exceptional aptitude.', -100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('apt-extreme', 'aptitude', 5, 'Ten (Eleven) Extreme Physique', 'Choose physique. 2x attainment growth in its path.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('apt-custom', 'aptitude', 6, 'Custom Extreme Physique', 'Choose two paths apart from Heaven. You are innately connected to this path starting with Dao Marks in these paths, and you also get 2x attainment growth in these paths.', -250, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('luck-nemesis', 'luck', 0, 'Nemesis Luck', 'During all stages of your cultivation, you will find a mortal enemy. At rank 1, another rank 1 will want to kill you for some unlikely reason. If you kill your nemesis or become a whole rank stronger than them, another will appear after a year’s delay. A nemesis will always be unusually strong for their rank.', 250, NULL, 1, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('luck-horizon', 'luck', 1, 'Horizon Graveyard Luck', 'The luck of everyone around you falls slowly but surely, eventually dooming them. Your allies, family, and anyone who you spend time with will suffer.', 200, NULL, 1, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('luck-peach', 'luck', 2, 'Peach-blossom Luck', 'You will have very good luck with the opposite sex. They are more receptive to your advances and more prepared to help you. Less effective on those above your rank but still noticeable.', -50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('luck-platinum', 'luck', 3, 'Platinum Luck', 'You are more likely to stumble upon commercial opportunities, especially auctions. Buy low, sell high.', -100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('luck-dogshit', 'luck', 4, 'Dog Shit Luck', 'Your luck is greatly improved, as if by rank 6 Dog Shit Luck.', -200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('luck-fortune', 'luck', 5, 'Fortune Rivalling Heaven', 'In addition to enjoying immense, Ma Hong Yun tier good fortune, you naturally have a greater understanding of luck and gain attainment in luck path 2x faster.', -400, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('soul-10k', 'soul', 0, 'Ten Thousand Man Soul', 'The soul foundation of a rank 5 expert. A clan leader of a super force, with all the resources that come with it, can expect to reach this soul foundation in 30 years, 20 if they use special or detrimental methods.', -50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('soul-100k', 'soul', 1, 'Hundred Thousand Man Soul', 'The soul foundation of a rank 6 immortal who has spent a great deal of effort strengthening their soul.', -100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('soul-1m', 'soul', 2, 'One Million Man Soul', 'The soul foundation of a great expert of a path that benefits from soul foundation, like refinement path, wisdom path, enslavement path, etc. Any higher, and the Dao mark interference from your soul will become too great.', -100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('soul-10m', 'soul', 3, 'Ten Million Man Soul', 'Only a soul path immortal would have a soul foundation this great. At this level, the interference from the soul path Dao marks on your soul would be detrimental to cultivating other paths. That is unless you have a way to get around this Dao mark interference. You naturally have a greater understanding of Soul and gain attainment in Soul path 2x faster.', -100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('ven-primordial', 'venerable', 0, 'Primordial Origin', 'Your base lifespan is increased by 10 times, and all life-extension methods are doubled in effectiveness. Lifespan drain does not affect you.', -350, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('ven-star', 'venerable', 1, 'Star Constellation', 'All your attainment gains are multiplied by 2. Additionally, all things that use mental energy require only half as much as they normally would.', -500, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('ven-limitless', 'venerable', 2, 'Limitless', 'You now gain 3 times as many Dao marks from any source as you otherwise would. Heaven''s Will doesn''t take into account the existence or effect of this perk when sending you tribulations as an immortal. This perk affects any Dao marks you may gain from any perks (This stacks with dao carver).', -300, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('ven-reckless', 'venerable', 3, 'Reckless Savage', 'You may transfer your true meaning to others at will or take it with their ‘consent’. ‘Consent’ may be forced, you can take attainments from captured souls, albeit more slowly than from a conscious, ensouled prisoner. You only gain attainment if they have more than you.', -400, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('ven-genesis', 'venerable', 4, 'Genesis Lotus', 'You can store primeval and immortal essence in a ‘bank’ within your aperture. This makes mortal cultivation easier. Stored essence gains interest at 10% per annum, in the your aperture world’s time.', -200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('ven-thieving', 'venerable', 5, 'Thieving Heaven', 'You gain a complete venerable inheritance. The established canon is disrupted as some random individual acquires Triple Qi Retraction, Star Constellation Chessboard, or Heaven and Earth Luck. Any Immortal Gu worms associated with these inheritances are at rank 6. Anticipate unpredictable consequences. If certain elements of the inheritance are unsuitable for a mortal aperture, they will be securely stored for future use when you attain an immortal aperture. If the immortal Gu worms linked to these inheritances already exist, they will be replaced with very similar Gu worms at Rank 6. Additionally, the inheritance will guide on using that Gu worm as a substitute.', -400, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('ven-redlotus', 'venerable', 6, 'Red Lotus', 'You get one save slot. Upon death or conscious activation, your will goes back in time to a point you designate. The save slot then disappears.', -250, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('ven-giant', 'venerable', 7, 'Giant Sun', 'You receive all options in the ''Luck'' category for free.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, '{"grantsCategories":["luck"]}');
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('ven-spectral', 'venerable', 8, 'Spectral Soul', 'Your will to win is unbreakable, and you can ignore all pain, despair, and negative emotions. Additionally, all soul path effects that reinforce, grow, or pacify your soul are two times more effective.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('ven-paradise', 'venerable', 9, 'Paradise Earth', 'You are born with 250 Dao Marks unrestrained heavenly Dao Marks, and your body is modified to withstand these Dao marks.', -500, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('ven-greatdream', 'venerable', 10, 'Great Dream', 'You may reach supreme grandmaster attainment via dream realms. 2x attainment gain in the dream path.', -200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('ven-heavenrefine', 'venerable', 11, 'Heaven Refining', 'All your Dao marks are non-conflicting.', -500, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('grab-3', 'grabBagBundles', 0, '3 Grab Bag Perks', 'Pick 3 of any grab bag perks', -50, NULL, 0, 0, NULL, 3, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('grab-5', 'grabBagBundles', 1, '5 Grab Bag Perks', 'Pick 5 of any grab bag perks', -100, NULL, 0, 0, NULL, 5, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('grab-7', 'grabBagBundles', 2, '7 Grab Bag Perks', 'Pick 7 of any grab bag perks', -150, NULL, 0, 0, NULL, 7, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('grab-10', 'grabBagBundles', 3, '10 Grab Bag Perks', 'Pick 10 of any grab bag perks', -200, NULL, 0, 0, NULL, 10, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier1-wealth', 'tier1', 0, 'Primeval Wealth', 'You acquire a rank 4 Primeval Elder Gu containing ten million primeval stones, equivalent to the wealth of a mid-sized clan. This option can be purchased multiple times.', -50, NULL, 0, 1, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier1-guset', 'tier1', 1, 'Gu Set', 'You can choose 10 Gu worms of the same path from rank 1 to 5, and they will manifest in your aperture when selected. If the chosen Gu worm can be refined to a higher rank, you can instantly achieve that at no cost, with the limitation not exceeding rank 5. This perk can be acquired multiple times.', -50, NULL, 0, 1, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier1-combat', 'tier1', 2, 'Close Combat Master', 'You are a battle genius and have mastered Krav Maga, Boxing, Brazilian Jiu-Jitsu, Grappling, and Muay Thai. Additionally, you possess master-level proficiency with a longsword, rapier, axe, and polearm.', -50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier1-recipes', 'tier1', 3, 'Mortal Recipes', 'You can select any 10 mortal Gu worms and gain their rank 1 through rank 5 recipes. The recipes will use modern materials, ensuring availability. This perk is repeatable.', -50, NULL, 0, 1, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier1-inhuman', 'tier1', 4, 'Inhuman Transformations', 'When transforming into a beastly form, you automatically gain the ability to move and control your body as if you were born in that form.', -50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier1-flyinggm', 'tier1', 5, 'Flying Grandmaster', 'You attain grandmaster proficiency in flying. Even geniuses renowned for their flying skill, at most, achieve quasi-grandmaster flying attainment.', -50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier1-longevity', 'tier1', 6, 'Longevity', 'You acquire a hundred-year lifespan Gu, which can be used to extend your lifespan or reserved for a different purpose.', -50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier2-dualdao', 'tier2', 0, 'Dual Dao', 'You can choose two paths, and these paths do not interfere with each other when used. This costs 50 CP less if you are picking the two paths from Custom Extreme Physique.', -100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier2-variantdao', 'tier2', 1, 'Variant Dao', 'If you are a variant human, you gain great grandmaster attainment in the path of your Dao. This means that dragon men gain great grandmaster in enslavement path, hairy men gain refinement path, etc. This doesn''t count towards your great grandmaster attainment limit. You naturally have a greater understanding of the path associated with your race and gain attainment in that path 2x faster.', -100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier2-secondap', 'tier2', 2, 'Second Aperture', 'You can awaken your second aperture at a time of your choosing. The second aperture functions as if created by rank 6 Second Aperture Gu, meaning it has no restriction on which rank it can rise to.', -100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier2-superguset', 'tier2', 3, 'Superior Gu Set', 'You may pick 10 Gu worms, and they will appear in your aperture when you choose. If the Gu worm you have chosen can be refined to a higher rank, you can do so instantly at no cost when you wish, but not to a rank higher than 5. Furthermore, these 10 Gu worms do not need to be fed. You can buy this perk twice.', -100, NULL, 0, 1, 2, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier2-immortalrecipes', 'tier2', 4, 'Immortal Recipes', 'You can choose 10 Gu worms, and you will obtain the rank 1 recipes, and the rank 2, etc., all the way to rank 9 for each Gu you choose. In other words, you will receive the recipe for the lowest possible rank that the Gu worm can be and up. The recipes will only contain materials that can all be found in the current era, with the higher-ranked recipes being a possible exception. They may contain very exotic or necessarily extinct, but still existing, materials.', -100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier2-borndao', 'tier2', 5, 'Born Dao', 'You are born with 50 Dao Marks for a path of your choice. Your body is modified to withstand these Dao marks. You can only grab this once per Dao mark.', -100, NULL, 0, 1, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier2-experience', 'tier2', 6, 'Experience', 'Before being born, you experience the entire life of a Random Gu master (Demontic, Righteous, lone, etc., your choice) who became immortal. The experience ends quickly after they die after reaching rank 6. If you are in the Alternative timeline, you can experience Fang Yuan’s first timeline from his point of view.', -100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier2-growth', 'tier2', 7, 'Growth', 'Choose any path, and you gain 2x attainment growth in it. You can only grab this once per path.', -100, NULL, 0, 1, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier2-greatlove', 'tier2', 8, 'Great Love', 'You become a grandmaster in social manipulation, reading people, manipulating agreements, and expressing false sincerity', -100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier3-vitalgu', 'tier3', 0, 'Vital Gu', 'When you pass the immortal ascension, your vital Gu, along with 2 other Gu, are guaranteed to advance with you to rank 6. You can also further refine a rank 6 immortal Gu for each path you have great grandmaster attainment in.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier3-inheritance', 'tier3', 1, 'Great Era Inheritance', 'You gain a rank 6 immortal inheritance that guides you from rank 1 to the peak of rank 6. The inheritance will be 500 years ahead of its time and contain Gu recipes and killer moves that are centuries ahead of its time. You may choose the inheritance to be a path of the great era like weapon path, pill path, etc.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier3-reinforced', 'tier3', 2, 'Reinforced Physique', 'If you have an extreme physique, you suffer none of the downsides. Your ascension will be on the high end of what a normal immortal might experience, relatively tame compared to ten extreme physiques. After this Heaven''s will isn''t going to hold back.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier3-autobalance', 'tier3', 3, 'Auto Balancer', 'When undergoing immortal ascension, your Heaven, Earth, and Human Qi will automatically be balanced for you. It''s guaranteed that you will pass immortal ascension.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier4-clone', 'tier4', 0, 'Clone', 'After awakening your aperture, you can create a clone of yourself at any time, you can choose if this clone shares your other perks and attainment levels.', -250, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier4-servant', 'tier4', 1, 'Servant of Heaven', 'You are considered an ally of Heaven''s Will and enjoy its favor. Fortuitous encounters are more likely, and your tribulations are easier to handle. This effect may intensify if you fight for Heavenly Court, target fate escapees, or confront enemies of heaven. Your heaven attainment increases at twice the normal speed. However, if you betray Heaven''s Will (such as by attacking fate or defying heaven), you lose this power.', -250, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier4-hidden', 'tier4', 2, 'Hidden Danger', 'At will, you can suppress your aura down to nothing or pretend to be multiple ranks lower than you are. Similarly, killer moves won''t reveal any aura if you choose to conceal it.', -200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier4-lifedeath', 'tier4', 3, 'Life and Death Aperture', 'Upon immortal ascension, you gain a life and death aperture. This means you will experience tribulations at half the normal strength, but you still gain the same amount of Dao marks. With this perk, you are guaranteed to get a high-grade blessed land, unless you possess an extreme physique, in which case you will gain a super-grade blessed land as usual.', -200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier4-daocarver', 'tier4', 4, 'Dao Carver', 'You now gain twice as many Dao marks from any source as you otherwise would. Heaven''s Will doesn''t take into account the existence or effect of this perk when sending you tribulations as an immortal. This perk affects any Dao marks you may gain from any perks. You now possess the cultivation prospects of a peak rank 8 expert or even a pseudo-venerable.', -300, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier4-antidiv', 'tier4', 5, 'Anti-Divination', 'You possess a rank 9 perpetual killer move, and you can choose the path it pertains to. Only a rank 9 wisdom path immortal equipped with a rank 9 Gu will have the ability to deduce information about you. Whenever someone attempts to make deductions about you, they either fail or receive an obfuscated answer. You have the flexibility to toggle this killer move on or off. If you wish for Heaven''s Will to send you tribulations, you can disable the killer move.', -300, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier4-rank8inherit', 'tier4', 6, 'Rank 8 Inheritance', 'Rank 8 inheritance. You may choose one or two paths and gain a rank 8 inheritance of the path(s) you choose. You may not pick heaven path. If you bought ''Great Era Inheritance'', this rank 8 inheritance may also be of a great era path along with the other features of ''Great era inheritance''. Regardless of if you bought ''Great era inheritance'', you may pick two aspects that the inheritance specializes in. If you only choose for the inheritance to contain one path you may instead pick four: Offense, Defense, Movement, Investigation, Concealment, Healing and Aperture Management. If you choose two paths then the inheritance contain an excellent method to duel cultivate these two paths. The inheritance does not contain any Gu worms, however it contains the knowledge or how to refine, feed and use several immortal Gu. The inheritance also contains peak strength mortal killer moves that cover all aspects, and how to empower these killer moves to immortal level by using immortal materials. Of course, the inheritance also details these killer moves when used with apropiate immortal Gu. The inheritance also comes with a battlefield killer move, you may choose one specialization for the battlefield killer move : Activation speed, Killing power, Concealment, Suppression. With this inheritance you cultivation will be smooth sailing from beginning to end.', -250, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier4-pocket', 'tier4', 7, 'Pocket Paradise', 'You obtain an orb containing a blessed land, choosing the path for this land. The orb is portable and can be stored within your aperture. Upon activation outside the aperture, the orb becomes immobile. Once placed, the orb functions as a blessed land with a controlled land spirit. When not in use, you can deactivate the orb and return it to your aperture. The orb supplies the blessed land with heaven and earth Qi, allowing you to move it to any of the five regions without issues. The blessed land has an interior size of 7,000 m², and time moves 40 times faster than in the Gu world. It generates resources related to the chosen path of the blessed land. The blessed land is a paradise and remains free from tribulations. It has robust resource production, yielding 50 immortal essence stones annually, with ample room for further development.', -300, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier5-dreamven', 'tier5', 0, 'Small Dream Immortal Venerable', 'You have master attainment in every path, providing uncanny and accurate intuitions about everything in the Gu world. You no longer have any restrictions on how many times you can buy grandmaster and great grandmaster attainment, and the price of buying attainment is halved.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, '{"attainmentCostMultiplier":0.5,"removesAttainmentLimits":true,"grantsAttainmentBaseline":"master"}');
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier5-maps', 'tier5', 1, 'Gu Maps', 'Gain a perfectly accurate map of the entire Gu world, stored in your head and projectable as a 3D hologram. The map includes detailed information on resource points, hidden inheritances, blessed lands, grotto-heavens, secluded domains, demographics, infrastructure, economic data, beast territory, and more. The map updates once a year.', -200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier5-prodigy', 'tier5', 2, 'Prodigy', 'In a path of your choice, you now have great grandmaster attainment and gain 4x attainment growth in it, with the talent to reach supreme grandmaster without needing outside help. This does not count towards the limit of how many great grandmaster attainments you can buy.', -200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier5-legendary', 'tier5', 3, 'Legendary Expert', 'You have quasi-supreme grandmaster attainment in a path of your choice, making you the undisputed expert in your path alive today. However, you will still need to exert a great deal of effort to raise your attainment to supreme grandmaster.', -350, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier5-vitalext', 'tier5', 4, 'Vital Gu Extension', 'Choose any Gu worm (except SAC). You acquire the capability to possess an additional Vital Gu worm. This Gu becomes your Vital Gu worm, accompanying your soul and manifesting when you first open your aperture at rank 1. It progressively advances in rank alongside you, reaching up to rank 9 automatically.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('tier5-pathfounder', 'tier5', 5, 'Path Founder', 'You may create your own path, starting off at master attainment with 2x attainment growth speed in it, along with potential for SGM. New paths are very hard to counter but won’t be quite so strong as dream path in terms of overall utility. The path should have an origin, two strengths and a weakness. For example, portal path would stem from space path (gaining somewhat from attainment in that path), be strong on speed and exploration but weak in aperture management.', -200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('premium-breakdream', 'premiumGu', 0, 'Break Dream', 'Dream Path: Destroys dream realms and counters dream path entities. Ideal for those who might face dream path moves, tribulations, or pesky enemies who hide in dream realms.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('premium-mastergu', 'premiumGu', 1, 'Master of Gu', 'Human Path: Contains the complete narrative of Reverend Insanity, including all unwritten chapters and side storys, When read it carves human path dao marks on the user, scaling with rank. It does not need immortal essence to use, only mental energy.', -250, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('premium-ptv', 'premiumGu', 2, 'Path to Victory', 'Wisdom Path: Allows you to create optimal step-by-step plans to fulfill goals, accounting even for factors the user is unaware of. Rank 6 can only account for Rank 6 entities and below. Uses a lot of mental energy and thoughts rather than immortal essence, making it useable for mortals (albeit only for smaller, short-term plans). You can use this like the light of wisdom to brute-force immortal gu recipes but this is extremely thought-intensive.', -350, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('premium-tribulation', 'premiumGu', 3, 'Tribulation', 'Heaven Path: Causes random tribulations against a target, whether it’s an immortal, object or beast. Using it often angers heaven’s will, eventually causing it to disfavour the user’s intent. Rank 6 causes earthly tribulations with a 5% chance of heavenly tribulations. Rank 7 causes heavenly tribulations with a 5% chance of grand tribulations… Target gains dao marks if it survives the tribulation.', -250, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('premium-chaos', 'premiumGu', 4, 'Chaos Flame Gu', 'Fire Path/Human Path (Consumable): Attaches a flame made out of Human path dao Marks to your soul. This flame can be summoned and manipulated, primarily as a weapon, instead of essence it uses mental and physical energy (but not lifespan). The strength of the flame depends on the strength of the body and soul. The flame, when not being physically manifested, can be used to nurture the body and soul and gradually strengthen them, and itself. This flame can be split off at effectively no cost and given to any willing individual, including mortals with no aptitude. When anyone uses the flame to strengthen themselves, a portion is fed back to the original user.', -200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('premium-solvent', 'premiumGu', 5, 'Universal Solvent Gu', 'Water Path/Refinement Path: Creates a special type of refinement water. Any materials placed in the water will be stripped of dao marks until the water is saturated. These dao marks themselves are broken down into a soup of pseudo-marks. The water created by this Gu only affects materials of the gu rank or below. This saturated water can be used when refining as a replacement for any materials of equivalent dao marks.', -200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('premium-selfoppression', 'premiumGu', 6, 'Self Oppression Gu', 'Enslavement Path: When used, anything enslaved under your control burdens its own soul with the cost of enslavement instead of you. You maintain control.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('premium-centraltime', 'premiumGu', 7, 'Heaven''s on Central Time', 'Time Path (Consumable): When used in an immortal aperture, the time between tribulations is determined by central continent time instead of internal aperture time.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('premium-mobileform', 'premiumGu', 8, 'Mobile Formation Immortal Gu', 'Formation Path: When adding Mobile Formation Immortal Gu to the formation, it allows the user to move the formation freely.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('premium-innatestrength', 'premiumGu', 9, 'Innate Strength Immortal Gu', 'Strength Path/Transformation Path: Innate Strength Immortal Gu allows the user to have the innate strength of the creature he transforms into.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('premium-humanstrength', 'premiumGu', 10, 'Human Strength Gu', 'Human Path/Strength Path: A reusable Gu. Once a Gu Master uses the Human Strength Gu, the Gu Master gains the strength of 25 human men permanently', -100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('premium-partial', 'premiumGu', 11, 'Partial Transformation Immortal Gu', 'Transformation Path/Rule Path: Partial Transformation Immortal Gu allows combining the best features of the transformation of different creatures into one creature.', -150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('premium-humanvessel', 'premiumGu', 12, 'Human Vessel Gu', 'Human Path: A reusable Gu. Once a Gu Master uses the Human Vessel Gu, the Gu Master will possess the ability to better withstand dao marks and experience reduced conflict between other dao marks.', -200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('premium-danghun', 'premiumGu', 13, 'Dang Hun Gu', 'Soul Path: A reusable Gu. Upon use, this gu expends soul foundation to create Guts gu at a significantly worse rate than Dang Hun Mountain. Using this gu consumes soul foundation instead of Primeval Essence.', -200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('mission-traditional', 'missions', 0, 'Traditional', 'Create an inheritance and a suitable inheritance ground. Describe what the trials and requirements there are to get your inheritance.', 100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('mission-paradise', 'missions', 1, 'Paradise', 'Enter the Grotto-Heaven Blue Dragon Whale at least once.', 100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('mission-kill', 'missions', 2, 'Problem? KILL!', 'Destroy a super force. You don''t have to kill all the members of that force, although it would be a good idea. You simply have to make it so that the super force doesn''t exist anymore.', 150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('mission-founding', 'missions', 3, 'Founding Ancestor', 'Create a super force, it may be a clan, sect, or other. The force has to nurture at least one immortal besides yourself.', 150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('mission-secluded', 'missions', 4, 'Secluded Domain', 'Obtain a secluded domain of heaven and earth. You have to have had ownership of a secluded domain for a month for this mission to be considered successful.', 200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('mission-supreme', 'missions', 5, 'Supreme Inheritance', 'Obtain a complete true inheritance of any venerable. Thieving Heaven''s three refinement opportunities from Lang Ya isn''t a true inheritance (and Thieving Heaven Venerable Inheritance perk doesn''t count either).', 200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('mission-homewrecker', 'missions', 6, 'Homewrecker', 'Your mission is to destroy 88 True Yang building. If 88 True Yang building is destroyed without your direct involvement, you fail.', 300, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('mission-heavenly', 'missions', 7, 'Heavenly Court', 'Join Heavenly Court and loyally serve its interests. You don''t have to save Fate Gu; you might even think it preferable if Red Lotus'' plan comes to fruition. But you have to do what you think is best for Heavenly Court.', 600, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('mission-david', 'missions', 8, 'David and Goliath', 'As a mortal, defeat a cultivator 3 ranks above you, or defeat a rank 6 immortal, or as an immortal, defeat a Gu Immortal one rank above you.', 150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('mission-feng', 'missions', 9, 'Eliminate Feng Jin Huang', 'Your mission is to personally kill Feng Jin Huang. If Feng Jin Huang is killed without your direct involvement, you fail.', 100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('mission-guardian', 'missions', 10, 'Eliminate Dao Guardian', 'Your mission is to personally kill a Dao Guardian. If a Dao Guardian is killed without your direct involvement, you fail.', 100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-nospoilers', 'drawbacks', 0, 'No Spoilers', 'You cannot share the contents of Reverend Insanity with anyone.', 50, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-daomono', 'drawbacks', 1, 'Dao Monogamous', 'Other paths interfere twice as much with the path of your vital Gu as they normally would. If you have dual dao, you cannot pick this drawback.', 100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-unundead', 'drawbacks', 2, 'Un-undead', 'You cannot turn into a zombie. For good or ill, you cannot become a zombie. Lifespan is always in short supply, and you no longer have a fail-safe. You will have to pay the price to bask in the light of wisdom.', 100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-trueword', 'drawbacks', 3, 'True to Your Word', 'You can never break an alliance agreement. Dao marks related to any contract or alliance can never be forcefully removed. You will have to be very careful with what you sign up for and always insist on a time limit.', 100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-mistress', 'drawbacks', 4, 'Like a Mistress', 'Gu worms you own need three times as much food to be properly fed.', 150, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-halflife', 'drawbacks', 5, 'Halved Lifespan', 'Your lifespan is halved, meaning if you are human, you only have 50 years to live. Lifespan extension methods are only half as effective as they normally would be.', 200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-daodunce', 'drawbacks', 6, 'Dao Dunce', 'You cannot increase your attainment level beyond what you buy in this character creator.', 300, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-indivisible', 'drawbacks', 7, 'Indivisible', 'You cannot create clones. Others may not create clones of you either. You may still create external wills.', 300, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-ofworld', 'drawbacks', 8, 'Of This World', 'For some reason, your soul and body are one of the Gu world, only your memories are of Earth, losing your otherworldly soul and Dao marks.', 300, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-truthbound', 'drawbacks', 9, 'Truthbound', 'You cannot knowingly lie. Nor can you avoid answering a question; you suffer growing and eventually debilitating pain until you answer. You may be misleading and deceptive.', 250, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-defy', 'drawbacks', 10, 'Defy Reality', 'You cannot knowingly tell the truth. If taken with Truthbound, you may never speak, write, or use gu worms to communicate in words, though there is no pain for lying. You’re stuck with pictures, expressions, and gestures.', 250, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-cliche', 'drawbacks', 11, 'Clichéd Daoist', 'You run into a lot of xianxia literary conventions. Glance at a jade beauty? You better believe you’re courting death! Often these conventions will be subverted; you may find that the young master was only pretending to be a drooling moron, that his illogical feud with you is part of a master plan. Even so, ensure you’re ready for battle whenever you enter a restaurant.', 100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-fangyuan', 'drawbacks', 12, 'Enemy - Fang Yuan', 'Fang Yuan knows about your powers and exploits from his previous life and plans to exploit you in some way. He has the support of many venerables; you will run into complications if you attempt to raze Gu Yue clan before he is born, though it is not impossible to nip him in the bud if you’re brave enough. (You can only grab this drawback if your in the Second timeline)', 100, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-shadow', 'drawbacks', 13, 'Enemy – Shadow Sect', 'Shadow Sect will try to kill you. They’ll discover you only after you draw attention to yourself or become an immortal. Initially, they’ll work indirectly by having Zombie Alliance or Defy go after you, escalating if you prove unexpectedly powerful or compromise their plans.', 200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-heavenlycourt', 'drawbacks', 14, 'Enemy – Heavenly Court', 'After you become immortal, Heavenly Court will eventually conclude you are an enemy of heaven’s will. Their wisdom path great experts will eventually track you down and make well-calculated assassination attempts. As with Shadow Sect, HC has many other priorities and will only react quickly and aggressively if you draw a lot of attention to yourself.', 200, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-principled', 'drawbacks', 15, 'Principled Protagonist', 'You can’t take demonic actions, from the point of view of both Gu World and Earth. For example, while the righteous path might try to enslave or exterminate variant humans, you may not even violate the Geneva Conventions. Sneak-attacking and so on are out too.', 250, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-lone', 'drawbacks', 16, 'Lone Cultivator', 'You may never ally with anyone longer than 24 hours, either in combat or in cultivation. You can still live with your parents or find lovers as long as you don’t give or receive aid in the above.', 250, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
INSERT INTO options (id, category_key, position, name, description, cost, image, negative, repeatable, max_count, picks, input_label, input_required, effects_json) VALUES ('draw-filial', 'drawbacks', 17, 'Filial Promise', 'You may not attack a human or variant human with the intent to kill.', 300, NULL, 0, 0, NULL, NULL, NULL, 0, NULL);
