INSERT INTO grab_bag_items (id, position, name, description) VALUES ('grab-reading', 0, 'Reading Materials', 'You have a popup window where you can read Reverend Insanity and the Reverend Insanity wiki; only you can read it.');
INSERT INTO grab_bag_items (id, position, name, description) VALUES ('grab-professor', 1, 'Gu Professor', 'You always know if an immortal Gu exists or not.');
INSERT INTO grab_bag_items (id, position, name, description) VALUES ('grab-polyglot', 2, 'Polyglot', 'You can speak and read the language of every region.');
INSERT INTO grab_bag_items (id, position, name, description) VALUES ('grab-1ksoul', 3, 'Thousand Man Soul', 'You are born with a 1,000 man soul. With this soul foundation, you could control more than 100,000 beasts with enslavement path methods. As a Gu master, your soul is also strong enough to beat all but rank 5 experts in a battle between souls.');
INSERT INTO grab_bag_items (id, position, name, description) VALUES ('grab-otherworld', 4, 'Otherworldly Dao', 'Choose what otherworldly Dao mark your soul comes with.');
INSERT INTO grab_bag_items (id, position, name, description) VALUES ('grab-settra', 5, 'Settra', 'Slavery Gu, of any rank, does not work on you.');
INSERT INTO grab_bag_items (id, position, name, description) VALUES ('grab-changewill', 6, 'Change Will', 'You can change an ideal of yourself to better fit the Gu world.');
INSERT INTO grab_bag_items (id, position, name, description) VALUES ('grab-memories', 7, 'Memories', 'Before being born, you gain the memories of a mortal whole life that wasn’t involved with Gu Master''s life.');
INSERT INTO grab_bag_items (id, position, name, description) VALUES ('grab-instant', 8, 'Instant Success', 'Gu worms that carve Dao marks on the user, like Black Boar Gu, Iron Bone Gu, etc., will have their full effects shown immediately and painlessly upon use, and they won''t need primeval essence to activate.');
INSERT INTO grab_bag_items (id, position, name, description) VALUES ('grab-mutated', 9, 'Mutated Soul', 'You may choose for your soul to be a mutated soul. For example, if you choose to have a wolfman soul, your soul would have wolf characteristics and would be many times stronger when controlling wolves.');
INSERT INTO grab_bag_items (id, position, name, description) VALUES ('grab-flying', 10, 'Flying Master', 'You now have master-level attainment in flying.');
INSERT INTO grab_bag_items (id, position, name, description) VALUES ('grab-secret', 11, 'Secret Manuals', 'As shown by Red Lotus Demon Venerable''s past, Gu cultivation isn''t the only cultivation system to exist in this world. There are secret manuals that mortals who haven''t or couldn''t awaken their aperture can use to produce supernatural effects. However, such cultivation is very minor compared to Gu Cultivation. You gain 3 secret manuals of your choice.');
